<?php
declare(strict_types=1);
require_once dirname(__DIR__).'/cms/layout.php';$user=require_login();
if($_SERVER['REQUEST_METHOD']==='POST'){require_csrf();$current=(string)($_POST['current_password']??'');$new=(string)($_POST['new_password']??'');$confirm=(string)($_POST['confirm_password']??'');$s=db()->prepare('SELECT password_hash FROM users WHERE id=?');$s->execute([$user['id']]);$hash=(string)$s->fetchColumn();if(!password_verify($current,$hash)){flash('error','当前密码不正确。');redirect('/admin/profile.php');}if(!valid_password($new)||$new!==$confirm){flash('error','新密码至少 12 位且包含字母和数字，两次输入必须一致。');redirect('/admin/profile.php');}db()->prepare('UPDATE users SET password_hash=?,must_change_password=0,updated_at=? WHERE id=?')->execute([password_hash($new,PASSWORD_DEFAULT),now_utc(),$user['id']]);audit('password_change','user',(int)$user['id']);flash('success','密码已更新。');redirect('/admin/');}
admin_header('修改密码',$user);?><section class="panel"><form method="post" style="max-width:620px"><?=csrf_input()?><div class="form-grid"><div class="field full"><label>当前密码</label><input type="password" name="current_password" required autocomplete="current-password"></div><div class="field"><label>新密码</label><input type="password" name="new_password" required minlength="12" autocomplete="new-password"></div><div class="field"><label>再次输入新密码</label><input type="password" name="confirm_password" required minlength="12" autocomplete="new-password"></div><div class="field full"><small>密码至少 12 位，必须包含字母和数字。</small></div></div><div class="form-actions"><button class="btn primary" type="submit">更新密码</button></div></form></section><?php admin_footer();
